import React from "react";
import {
  AbsoluteFill,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
// Schema streamlined to reflect the removal of text and statue colors


export type LadyJusticeScaleProps = Record<string, any>;

// Deterministic ambient particles component
const AmbientDust: React.FC<{ frame: number; width: number; height: number }> = ({
  frame,
  width,
  height,
}) => {
  return (
    <svg
      style={{
        position: "absolute",
        top: 0,
        left: 0,
        width: "100%",
        height: "100%",
        pointerEvents: "none",
        opacity: 0.35,
        transition: "none",
      }}
    >
      {Array.from({ length: 60 }).map((_, i) => {
        // Deterministic pseudo-randomness based on index
        const startX = Math.abs(Math.sin(i * 13.5) * width);
        const startY = Math.abs(Math.cos(i * 41.2) * height);
        const speed = Math.abs(Math.sin(i * 3.1)) * 2 + 0.5;
        const sway = Math.sin(frame * 0.02 + i) * 30;
        const currentY = (startY - frame * speed + height * 2) % height;
        const size = Math.abs(Math.sin(i * 8.4)) * 3 + 1;
        const opacity = Math.abs(Math.sin(frame * 0.05 + i)) * 0.5 + 0.1;

        return (
          <circle
            key={i}
            cx={startX + sway}
            cy={currentY}
            r={size}
            fill="#FFFFFF"
            opacity={opacity}
            style={{ transition: "none" }}
          />
        );
      })}
    </svg>
  );
};

// Reusable Photorealistic 3D Cylinder Helper
const Cylinder: React.FC<{
  cx: number;
  cy: number;
  rx: number;
  ry: number;
  h: number;
  color: string;
  overlay: string;
}> = ({ cx, cy, rx, ry, h, color, overlay }) => (
  <g>
    {/* Body */}
    <path
      d={`M ${cx - rx} ${cy} L ${cx - rx} ${cy + h} A ${rx} ${ry} 0 0 0 ${cx + rx} ${cy + h} L ${cx + rx} ${cy} Z`}
      fill={color}
    />
    <path
      d={`M ${cx - rx} ${cy} L ${cx - rx} ${cy + h} A ${rx} ${ry} 0 0 0 ${cx + rx} ${cy + h} L ${cx + rx} ${cy} Z`}
      fill={overlay}
    />
    {/* Top Surface */}
    <ellipse cx={cx} cy={cy} rx={rx} ry={ry} fill={color} />
    <ellipse cx={cx} cy={cy} rx={rx} ry={ry} fill="rgba(255,255,255,0.15)" />
  </g>
);

const ScalePan: React.FC<{
  x: number;
  y: number;
  swingAngle: number;
  scaleColor: string;
}> = ({ x, y, swingAngle, scaleColor }) => {
  const dropLength = 600;
  const panWidth = 160;

  return (
    <g
      transform={`rotate(${swingAngle}, ${x}, ${y})`}
      style={{ transition: "none" }}
      filter="url(#shadow)"
    >
      {/* Chains */}
      <line x1={x} y1={y} x2={x} y2={y + dropLength + 10} stroke={scaleColor} strokeWidth="6" />
      <line x1={x} y1={y} x2={x} y2={y + dropLength + 10} stroke="rgba(0,0,0,0.5)" strokeWidth="6" strokeDasharray="12 6" />

      <line x1={x} y1={y} x2={x - panWidth + 25} y2={y + dropLength} stroke={scaleColor} strokeWidth="8" />
      <line x1={x} y1={y} x2={x - panWidth + 25} y2={y + dropLength} stroke="url(#horizOverlay)" strokeWidth="8" />
      <line x1={x} y1={y} x2={x - panWidth + 25} y2={y + dropLength} stroke="rgba(0,0,0,0.6)" strokeWidth="8" strokeDasharray="14 7" />

      <line x1={x} y1={y} x2={x + panWidth - 25} y2={y + dropLength} stroke={scaleColor} strokeWidth="8" />
      <line x1={x} y1={y} x2={x + panWidth - 25} y2={y + dropLength} stroke="url(#horizOverlay)" strokeWidth="8" />
      <line x1={x} y1={y} x2={x + panWidth - 25} y2={y + dropLength} stroke="rgba(0,0,0,0.6)" strokeWidth="8" strokeDasharray="14 7" />

      {/* Bowl Exterior */}
      <path
        d={`M ${x - panWidth} ${y + dropLength} A ${panWidth} ${panWidth * 0.65} 0 0 0 ${x + panWidth} ${y + dropLength} Z`}
        fill={scaleColor}
      />
      <path
        d={`M ${x - panWidth} ${y + dropLength} A ${panWidth} ${panWidth * 0.65} 0 0 0 ${x + panWidth} ${y + dropLength} Z`}
        fill="url(#bowlOverlay)"
      />

      {/* Bowl Interior Opening */}
      <ellipse cx={x} cy={y + dropLength} rx={panWidth} ry="35" fill={scaleColor} />
      <ellipse cx={x} cy={y + dropLength} rx={panWidth} ry="35" fill="rgba(0,0,0,0.75)" />
      <ellipse cx={x} cy={y + dropLength} rx={panWidth} ry="35" fill="url(#bowlOverlay)" opacity={0.3} />

      {/* Front Rim Highlight */}
      <path
        d={`M ${x - panWidth} ${y + dropLength} A ${panWidth} 35 0 0 0 ${x + panWidth} ${y + dropLength}`}
        fill="none"
        stroke="rgba(255,255,255,0.7)"
        strokeWidth="4"
      />
    </g>
  );
};

const LadyJusticeScale: React.FC<LadyJusticeScaleProps> = ({
  backgroundColor = "#080a0f",
  transparentBackground = false,
  durationInSeconds = 12,
  scaleColor = "#D4AF37",
  unevennessSpeed = 1.5,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Safe background logic with cinematic spotlight vignette
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  const bgStyle: React.CSSProperties = {
    backgroundColor: bgColor,
    backgroundImage: transparentBackground
      ? undefined
      : `radial-gradient(circle at 50% 40%, ${backgroundColor} 0%, #000000 120%)`,
    transition: "none",
  };

  // --- Animation Logic for the Uneven Scale ---
  const getAngleAtFrame = (f: number) => {
    const time = f / fps;
    const speed = unevennessSpeed;

    const rawAngle =
      Math.sin(time * speed * 2.1) * 12 +
      Math.cos(time * speed * 1.3) * -10 +
      Math.sin(time * speed * 0.7) * 20 +
      Math.pow(Math.sin(time * speed * 0.4), 3) * 35; 

    // Restrict extreme swinging
    const clampedAngle = Math.max(-40, Math.min(40, rawAngle));

    // Smoothly introduce the movement over the first 45 frames
    const fade = interpolate(f, [0, 45], [0, 1], { extrapolateRight: "clamp" });
    return clampedAngle * fade;
  };

  const scaleAngle = getAngleAtFrame(frame);
  const previousScaleAngle = getAngleAtFrame(Math.max(0, frame - 5));
  
  // Velocity calculation determines the pendulum swinging of the pans
  const angularVelocity = scaleAngle - previousScaleAngle;
  const panSwing = angularVelocity * -0.6; 

  // --- Center the Scale Geometry ---
  const pivotX = width / 2;
  const pivotY = height * 0.3; // Approx 576
  const beamRadius = 400;
  const baseY = height * 0.88; // Approx 1689

  const angleRad = (scaleAngle * Math.PI) / 180;
  const leftPanX = pivotX - beamRadius * Math.cos(angleRad);
  const leftPanY = pivotY - beamRadius * Math.sin(angleRad);
  const rightPanX = pivotX + beamRadius * Math.cos(angleRad);
  const rightPanY = pivotY + beamRadius * Math.sin(angleRad);

  return (
    <AbsoluteFill style={bgStyle}>
      <AmbientDust frame={frame} width={width} height={height} />

      {/* Main SVG Container */}
      <svg
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        style={{ position: "absolute", top: 0, left: 0, transition: "none" }}
      >
        {/* Photorealistic Lighting & Gradients */}
        <defs>
          <linearGradient id="cylOverlay" x1="0%" y1="0%" x2="100%" y2="0%">
            <stop offset="0%" stopColor="#000" stopOpacity="0.85" />
            <stop offset="15%" stopColor="#fff" stopOpacity="0.5" />
            <stop offset="30%" stopColor="#fff" stopOpacity="0.95" />
            <stop offset="50%" stopColor="#000" stopOpacity="0.1" />
            <stop offset="85%" stopColor="#000" stopOpacity="0.8" />
            <stop offset="100%" stopColor="#fff" stopOpacity="0.4" />
          </linearGradient>

          <linearGradient id="horizOverlay" x1="0%" y1="0%" x2="0%" y2="100%">
            <stop offset="0%" stopColor="#fff" stopOpacity="0.9" />
            <stop offset="20%" stopColor="#fff" stopOpacity="0.3" />
            <stop offset="50%" stopColor="#000" stopOpacity="0.2" />
            <stop offset="80%" stopColor="#000" stopOpacity="0.65" />
            <stop offset="100%" stopColor="#000" stopOpacity="0.95" />
          </linearGradient>

          <radialGradient id="bowlOverlay" cx="35%" cy="30%" r="70%">
            <stop offset="0%" stopColor="#fff" stopOpacity="0.8" />
            <stop offset="30%" stopColor="#fff" stopOpacity="0.1" />
            <stop offset="70%" stopColor="#000" stopOpacity="0.6" />
            <stop offset="100%" stopColor="#000" stopOpacity="0.95" />
          </radialGradient>

          <filter id="shadow" x="-30%" y="-30%" width="160%" height="160%">
            <feDropShadow dx="0" dy="25" stdDeviation="15" floodColor="#000" floodOpacity="0.8" />
          </filter>
          
          <filter id="softShadow" x="-30%" y="-30%" width="160%" height="160%">
            <feDropShadow dx="0" dy="10" stdDeviation="8" floodColor="#000" floodOpacity="0.6" />
          </filter>
        </defs>

        {/* SCALE STAND (Background Pillar & Base) */}
        <g style={{ transition: "none" }}>
          {/* Main Pillar Shaft */}
          <Cylinder cx={pivotX} cy={pivotY} rx={35} ry={15} h={baseY - 120 - pivotY} color={scaleColor} overlay="url(#cylOverlay)" />
          
          {/* Decorative Rings on Shaft */}
          <Cylinder cx={pivotX} cy={pivotY + 180} rx={48} ry={20} h={18} color={scaleColor} overlay="url(#cylOverlay)" />
          <Cylinder cx={pivotX} cy={pivotY + 380} rx={48} ry={20} h={18} color={scaleColor} overlay="url(#cylOverlay)" />

          {/* Stepped Base Tiers */}
          <Cylinder cx={pivotX} cy={baseY - 120} rx={160} ry={40} h={40} color={scaleColor} overlay="url(#cylOverlay)" />
          <Cylinder cx={pivotX} cy={baseY - 80} rx={250} ry={55} h={40} color={scaleColor} overlay="url(#cylOverlay)" />
          <Cylinder cx={pivotX} cy={baseY - 40} rx={350} ry={70} h={40} color={scaleColor} overlay="url(#cylOverlay)" />

          {/* Static Center Marker (for Needle) */}
          <polygon
            points={`${pivotX - 18},${pivotY + 310} ${pivotX + 18},${pivotY + 310} ${pivotX},${pivotY + 270}`}
            fill={scaleColor}
            filter="url(#softShadow)"
          />
          <polygon
            points={`${pivotX - 18},${pivotY + 310} ${pivotX + 18},${pivotY + 310} ${pivotX},${pivotY + 270}`}
            fill="url(#horizOverlay)"
          />
        </g>

        {/* ROTATING BEAM ASSEMBLY */}
        <g
          transform={`rotate(${scaleAngle}, ${pivotX}, ${pivotY})`}
          style={{ transition: "none" }}
        >
          {/* Main Balance Beam */}
          <rect
            x={pivotX - beamRadius}
            y={pivotY - 16}
            width={beamRadius * 2}
            height={32}
            rx={16}
            fill={scaleColor}
            filter="url(#shadow)"
          />
          <rect
            x={pivotX - beamRadius}
            y={pivotY - 16}
            width={beamRadius * 2}
            height={32}
            rx={16}
            fill="url(#horizOverlay)"
          />
          
          {/* Beam End Joints */}
          <circle cx={pivotX - beamRadius} cy={pivotY} r={28} fill={scaleColor} />
          <circle cx={pivotX - beamRadius} cy={pivotY} r={28} fill="url(#bowlOverlay)" />
          
          <circle cx={pivotX + beamRadius} cy={pivotY} r={28} fill={scaleColor} />
          <circle cx={pivotX + beamRadius} cy={pivotY} r={28} fill="url(#bowlOverlay)" />

          {/* Beam Center Hub Ring */}
          <circle cx={pivotX} cy={pivotY} r={55} fill={scaleColor} filter="url(#shadow)" />
          <circle cx={pivotX} cy={pivotY} r={55} fill="url(#bowlOverlay)" />

          {/* The Needle (Points down, shifts with rotation) */}
          <polygon
            points={`${pivotX - 12},${pivotY} ${pivotX + 12},${pivotY} ${pivotX},${pivotY + 300}`}
            fill={scaleColor}
            filter="url(#shadow)"
          />
          <polygon
            points={`${pivotX - 12},${pivotY} ${pivotX + 12},${pivotY} ${pivotX},${pivotY + 300}`}
            fill="url(#cylOverlay)"
          />
        </g>

        {/* FRONT PIVOT CAP (Static Hub Pin) */}
        <circle cx={pivotX} cy={pivotY} r={35} fill={scaleColor} filter="url(#shadow)" />
        <circle cx={pivotX} cy={pivotY} r={35} fill="url(#bowlOverlay)" />
        <circle cx={pivotX} cy={pivotY} r={12} fill="#000" opacity={0.65} />

        {/* DANGLING PANS */}
        <ScalePan
          x={leftPanX}
          y={leftPanY}
          swingAngle={panSwing}
          scaleColor={scaleColor}
        />
        <ScalePan
          x={rightPanX}
          y={rightPanY}
          swingAngle={panSwing}
          scaleColor={scaleColor}
        />
      </svg>
    </AbsoluteFill>
  );
};

export default LadyJusticeScale;